package com.bulwarkspecrange;

import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;

final class BulwarkRange
{
    static final int RADIUS = 5;
    private static final int SPECIAL_ENERGY_REQUIRED = 500; // RuneLite stores 100% as 1000.

    private BulwarkRange()
    {
    }

    static boolean isVisible(int weaponId, int specialEnergy, boolean requireSpecialEnergy)
    {
        return (weaponId == ItemID.DINHS_BULWARK || weaponId == ItemID.DINHS_BULWARK_ORNAMENT)
            && (!requireSpecialEnergy || specialEnergy >= SPECIAL_ENERGY_REQUIRED);
    }

    static void forEachTile(WorldPoint center, TileConsumer consumer)
    {
        for (int dx = -RADIUS; dx <= RADIUS; dx++)
        {
            for (int dy = -RADIUS; dy <= RADIUS; dy++)
            {
                consumer.accept(center.dx(dx).dy(dy), dx, dy);
            }
        }
    }

    @FunctionalInterface
    interface TileConsumer
    {
        void accept(WorldPoint tile, int dx, int dy);
    }
}

package com.bulwarkspecrange;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(BulwarkSpecRangeConfig.GROUP)
public interface BulwarkSpecRangeConfig extends Config
{
    String GROUP = "bulwarkspecrange";

    @ConfigItem(
        keyName = "requireSpecialEnergy",
        name = "Require 50% special energy",
        description = "Show the area only when you have at least 50% special attack energy.",
        position = 0
    )
    default boolean requireSpecialEnergy()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showOutline",
        name = "Show outline",
        description = "Draw a line around the area. Turn off to show the fill on its own.",
        position = 1
    )
    default boolean showOutline()
    {
        return true;
    }

    @Alpha
    @ConfigItem(
        keyName = "outlineColor",
        name = "Outline color",
        description = "Color and opacity of the area outline.",
        position = 2
    )
    default Color outlineColor()
    {
        return new Color(0, 39, 207, 205);
    }

    @Alpha
    @ConfigItem(
        keyName = "fillColor",
        name = "Fill color",
        description = "Color and opacity inside the outline. Set opacity to zero for an outline only.",
        position = 3
    )
    default Color fillColor()
    {
        return new Color(0, 10, 255, 50);
    }

    @Range(min = 1, max = 6)
    @ConfigItem(
        keyName = "outlineWidth",
        name = "Outline width",
        description = "Thickness of the outline in pixels.",
        position = 4
    )
    default double outlineWidth()
    {
        return 1.25;
    }

    @ConfigItem(
        keyName = "highlightCorners",
        name = "Highlight corners",
        description = "Draw the four corners with a brighter, thicker outline.",
        position = 5
    )
    default boolean highlightCorners()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showCenterTile",
        name = "Show center tile",
        description = "Outline your true tile in the center of the marked area.",
        position = 6
    )
    default boolean showCenterTile()
    {
        return false;
    }
}

package com.bulwarkspecrange;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class BulwarkSpecRangeOverlay extends Overlay
{
    private static final Color CENTER_COLOR = new Color(185, 209, 255, 230);
    private static final Color CENTER_BACKING = new Color(17, 27, 54, 175);
    private static final BasicStroke CENTER_STROKE = stroke(1.25f);
    private static final BasicStroke CENTER_BACKING_STROKE = stroke(3);

    private final Client client;
    private final BulwarkSpecRangeConfig config;

    @Inject
    BulwarkSpecRangeOverlay(Client client, BulwarkSpecRangeConfig config)
    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.getGameState() != GameState.LOGGED_IN || !isAvailable())
        {
            return null;
        }

        Player player = client.getLocalPlayer();
        if (player == null)
        {
            return null;
        }

        WorldView worldView = player.getWorldView();
        Color fillColor = config.fillColor();
        Color outlineColor = config.outlineColor();
        boolean showOutline = config.showOutline() && outlineColor.getAlpha() > 0;
        boolean showCenterTile = config.showCenterTile();
        boolean highlightCorners = config.highlightCorners();
        Path2D fill = new Path2D.Float();
        Path2D border = new Path2D.Float();
        Path2D corners = new Path2D.Float();
        Path2D centerTile = new Path2D.Float();

        BulwarkRange.forEachTile(player.getWorldLocation(), (tile, dx, dy) ->
        {
            LocalPoint local = LocalPoint.fromWorld(worldView, tile);
            Polygon polygon = local == null ? null : Perspective.getCanvasTilePoly(client, local);
            if (polygon == null)
            {
                return;
            }

            fill.append(polygon, false);
            if (showCenterTile && dx == 0 && dy == 0)
            {
                centerTile.append(polygon, false);
            }
            if (!showOutline)
            {
                return;
            }

            // Polygon vertices are (-x,-y), (+x,-y), (+x,+y), (-x,+y) relative to the tile's center.
            boolean cornerTile = highlightCorners
                && Math.abs(dx) == BulwarkRange.RADIUS && Math.abs(dy) == BulwarkRange.RADIUS;
            Path2D edgePath = cornerTile ? corners : border;
            if (dx == -BulwarkRange.RADIUS)
            {
                addEdge(edgePath, polygon, 3, 0);
            }
            if (dy == BulwarkRange.RADIUS)
            {
                addEdge(edgePath, polygon, 2, 3);
            }
            if (dx == BulwarkRange.RADIUS)
            {
                addEdge(edgePath, polygon, 1, 2);
            }
            if (dy == -BulwarkRange.RADIUS)
            {
                addEdge(edgePath, polygon, 0, 1);
            }
        });

        Graphics2D overlayGraphics = (Graphics2D) graphics.create();
        try
        {
            overlayGraphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            overlayGraphics.setColor(fillColor);
            overlayGraphics.fill(fill);
            if (showOutline)
            {
                float width = (float) config.outlineWidth();
                overlayGraphics.setColor(new Color(32, 22, 15, outlineColor.getAlpha() * 85 / 100));
                overlayGraphics.setStroke(stroke(width + 2.25f));
                overlayGraphics.draw(border);
                overlayGraphics.draw(corners);
                overlayGraphics.setColor(outlineColor);
                overlayGraphics.setStroke(stroke(width));
                overlayGraphics.draw(border);
                if (highlightCorners)
                {
                    overlayGraphics.setColor(cornerColor(outlineColor));
                    overlayGraphics.setStroke(stroke(width + 1));
                    overlayGraphics.draw(corners);
                }
            }
            if (showCenterTile)
            {
                overlayGraphics.setColor(CENTER_BACKING);
                overlayGraphics.setStroke(CENTER_BACKING_STROKE);
                overlayGraphics.draw(centerTile);
                overlayGraphics.setColor(CENTER_COLOR);
                overlayGraphics.setStroke(CENTER_STROKE);
                overlayGraphics.draw(centerTile);
            }
        }
        finally
        {
            overlayGraphics.dispose();
        }

        return null;
    }

    private boolean isAvailable()
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
        Item weapon = equipment == null ? null : equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
        return weapon != null && BulwarkRange.isVisible(
            weapon.getId(), client.getVarpValue(VarPlayerID.SA_ENERGY), config.requireSpecialEnergy());
    }

    private static void addEdge(Path2D border, Polygon polygon, int from, int to)
    {
        border.moveTo(polygon.xpoints[from], polygon.ypoints[from]);
        border.lineTo(polygon.xpoints[to], polygon.ypoints[to]);
    }

    private static BasicStroke stroke(float width)
    {
        return new BasicStroke(width, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
    }

    private static Color cornerColor(Color outline)
    {
        return new Color(
            (outline.getRed() * 3 + 510) / 5,
            (outline.getGreen() * 3 + 510) / 5,
            (outline.getBlue() * 3 + 510) / 5,
            Math.min(255, outline.getAlpha() * 6 / 5));
    }
}

package com.bulwarkspecrange;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Bulwark Spec Range",
    description = "Shows the Shield Bash area when you have Dinh's bulwark equipped, with an optional special energy requirement.",
    tags = {"dinh", "shield bash", "special attack", "range", "tile"}
)
public class BulwarkSpecRangePlugin extends Plugin
{
    @Inject
    private OverlayManager overlayManager;

    @Inject
    private BulwarkSpecRangeOverlay overlay;

    @Provides
    BulwarkSpecRangeConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BulwarkSpecRangeConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
    }
}

package com.bulwarkspecrange;

import com.google.inject.Guice;
import com.google.inject.Injector;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.io.File;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.stream.Collectors;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.client.RuneLite;
import net.runelite.client.RuneLiteModule;
import net.runelite.client.RuntimeConfigLoader;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Response;
import okhttp3.ResponseBody;

public final class BulwarkConfigTest
{
    public static void main(String[] args) throws Exception
    {
        OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain ->
            new Response.Builder()
                .request(chain.request()).protocol(Protocol.HTTP_1_1).code(200).message("OK")
                .body(ResponseBody.create(MediaType.parse("application/json"), "{}")).build()
        ).build();
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (proxy, method, arguments) -> null);
        Injector injector = Guice.createInjector(new RuneLiteModule(
            http, () -> client, new RuntimeConfigLoader(http), true, false, true,
            new File(RuneLite.RUNELITE_DIR, "test-session"), null, null, false, false));
        RuneLite.setInjector(injector);
        try
        {
            verifyConfig(injector);
        }
        finally
        {
            injector.getInstance(ScheduledExecutorService.class).shutdownNow();
            http.dispatcher().executorService().shutdownNow();
        }
    }

    private static void verifyConfig(Injector injector) throws Exception
    {
        ConfigManager configManager = injector.getInstance(ConfigManager.class);
        configManager.load();
        PluginManager pluginManager = injector.getInstance(PluginManager.class);
        Plugin plugin = pluginManager.loadPlugins(List.of(BulwarkSpecRangePlugin.class), null).get(0);

        Config detected = pluginManager.getPluginConfigProxy(plugin);
        check(detected instanceof BulwarkSpecRangeConfig, "RuneLite must discover the configuration");
        BulwarkSpecRangeConfig config = (BulwarkSpecRangeConfig) detected;
        configManager.setDefaultConfiguration(config, false);
        check(configManager.getConfigDescriptor(config).getItems().stream()
            .map(item -> item.getItem().keyName()).collect(Collectors.toList())
            .equals(List.of("requireSpecialEnergy", "showOutline", "outlineColor", "fillColor", "outlineWidth", "highlightCorners", "showCenterTile")), "RuneLite settings order");
        check(config.outlineColor().equals(new Color(0, 39, 207, 205)), "Default outline color and opacity");
        check(config.fillColor().equals(new Color(0, 10, 255, 50)), "Default fill and opacity");
        check(config.outlineWidth() == 1.25 && config.highlightCorners() && config.showOutline(), "Default outline");
        check(config.requireSpecialEnergy(), "Require 50% by default");
        check(!config.showCenterTile(), "Center tile is off by default");
        verifyCog(injector, pluginManager, plugin);

        Color selected = new Color(55, 170, 224, 125);
        configManager.setConfiguration(BulwarkSpecRangeConfig.GROUP, "outlineColor", selected);
        configManager.setConfiguration(BulwarkSpecRangeConfig.GROUP, "highlightCorners", false);
        configManager.setConfiguration(BulwarkSpecRangeConfig.GROUP, "showOutline", false);
        configManager.setConfiguration(BulwarkSpecRangeConfig.GROUP, "requireSpecialEnergy", false);
        configManager.setConfiguration(BulwarkSpecRangeConfig.GROUP, "showCenterTile", true);
        check(config.outlineColor().equals(selected), "Color and alpha update");
        check(!config.highlightCorners(), "Corner preference update");
        check(!config.showOutline() && !config.requireSpecialEnergy(), "New toggles update live");
        check(config.showCenterTile(), "Center tile preference updates live");
        System.out.println("PASS: RuneLite's cog opens all seven settings. Defaults and live updates work.");
    }

    private static void verifyCog(Injector injector, PluginManager pluginManager, Plugin plugin) throws Exception
    {
        Class<?> panelType = Class.forName("net.runelite.client.plugins.config.PluginListPanel");
        Method rebuildPluginList = panelType.getDeclaredMethod("rebuildPluginList");
        rebuildPluginList.setAccessible(true);
        pluginManager.add(plugin);
        SwingUtilities.invokeAndWait(() ->
        {
            Container panel = (Container) injector.getInstance(panelType);
            try
            {
                rebuildPluginList.invoke(panel);
            }
            catch (ReflectiveOperationException e)
            {
                throw new AssertionError(e);
            }
            JButton cog = findCog(panel);
            check(cog != null && cog.isVisible(), "RuneLite settings cog is visible");
            cog.doClick(0);
            Container tabs = panel.getParent();
            check(hasLabel(tabs, "Require 50% special energy") && hasLabel(tabs, "Show outline")
                && hasLabel(tabs, "Outline color") && hasLabel(tabs, "Fill color")
                && hasLabel(tabs, "Outline width") && hasLabel(tabs, "Highlight corners")
                && hasLabel(tabs, "Show center tile"), "Cog opens the settings form");
        });
    }

    private static JButton findCog(Container container)
    {
        for (Component child : container.getComponents())
        {
            if (child instanceof JButton && "Edit plugin configuration".equals(((JButton) child).getToolTipText()))
            {
                return (JButton) child;
            }
            JButton nested = child instanceof Container ? findCog((Container) child) : null;
            if (nested != null)
            {
                return nested;
            }
        }
        return null;
    }

    private static boolean hasLabel(Container container, String text)
    {
        for (Component child : container.getComponents())
        {
            if (child instanceof JLabel && text.equals(((JLabel) child).getText()))
            {
                return true;
            }
            if (child instanceof Container && hasLabel((Container) child, text))
            {
                return true;
            }
        }
        return false;
    }

    private static void check(boolean condition, String reason)
    {
        if (!condition)
        {
            throw new AssertionError(reason);
        }
    }
}

